import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadSubrotoData(){const e=readFileSync(resolve(__dirname,"../../subroto-cup-explorer/subroto-data.js"),"utf-8");return new Function(e+"\nreturn { SUBROTO_INFO, AGE_CATEGORIES, FAMOUS_ALUMNI, PLAYER_PIPELINE, REFERENCES };")()}describe("Subroto Cup Explorer — Data Tests",()=>{let e;beforeAll(()=>{e=loadSubrotoData()}),describe("SUBROTO_INFO metadata",()=>{it("contains correct Subroto Cup metadata and founding year 1960",()=>{expect(e.SUBROTO_INFO.id).toBe("subroto-cup"),expect(e.SUBROTO_INFO.title).toContain("Subroto Cup"),expect(e.SUBROTO_INFO.foundedYear).toBe("1960 CE"),expect(e.SUBROTO_INFO.namesake).toContain("Subroto Mukerjee")}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(e.SUBROTO_INFO.quickStats)).toBe(!0),expect(e.SUBROTO_INFO.quickStats.length).toBe(6)})}),describe("AGE_CATEGORIES & FAMOUS_ALUMNI",()=>{it("contains U-14, U-17 age divisions and famous alumni like Sunil Chhetri",()=>{expect(Array.isArray(e.AGE_CATEGORIES)).toBe(!0),expect(e.AGE_CATEGORIES.length).toBeGreaterThanOrEqual(3),expect(Array.isArray(e.FAMOUS_ALUMNI)).toBe(!0);const t=e.FAMOUS_ALUMNI.find(e=>e.name.includes("Chhetri"));expect(t).toBeDefined()})}),describe("PLAYER_PIPELINE & REFERENCES",()=>{it("contains youth player pipeline steps and reference citations",()=>{expect(Array.isArray(e.PLAYER_PIPELINE)).toBe(!0),expect(e.PLAYER_PIPELINE.length).toBeGreaterThanOrEqual(4),expect(Array.isArray(e.REFERENCES)).toBe(!0),expect(e.REFERENCES.length).toBeGreaterThanOrEqual(2)})})});